//! Coverage of Smith's genus-3 hyperelliptic-to-quartic isogeny, per curve and
//! per isogeny class, over small odd prime fields.
//!
//! Smith (Eurocrypt 2008; J. Cryptology 22 (2009)) maps the Jacobian of a
//! genus-3 hyperelliptic curve `H: y^2 = f(x)` over `F_q` (`q` odd) to the
//! Jacobian of a curve `C`, generically a plane quartic, along an explicit
//! `(2,2,2)`-isogeny.  It is computed with Recillas' trigonal construction.
//! The kernel must be a Galois-stable maximal isotropic subgroup of
//! `J_H[2]` of "pair type": one generated by the classes
//! `[(alpha_i) - (beta_i)]` of a partition of the eight Weierstrass points
//! into four pairs.  Galois stability of that subgroup is equivalent to
//! Frobenius permuting the roots of `f` so as to preserve the partition.
//!
//! For each `f` this module measures:
//!
//! * the Frobenius cycle type on the roots (distinct-degree factorisation);
//! * whether a stable pair partition exists (**direct Smith coverage**);
//! * whether any of the 135 maximal isotropic subgroups is stable (pair type
//!   or the other 30), computed from the explicit `Sp_6(F_2)` action;
//! * the `L`-polynomial from exact point counts over `F_p, F_{p^2},
//!   F_{p^3}`, i.e. the `F_p`-isogeny class (Tate).
//!
//! From those come the **class closure**: the share of hyperelliptic curves
//! whose isogeny class contains a hyperelliptic curve with a stable pair
//! partition.  That is the ceiling for "walk inside the hyperelliptic
//! locus, then apply Smith".  A necessary class-level condition is checked
//! too.  If a Frobenius-stable Lagrangian `W` exists then
//! `chi_pi mod 2 = g(T) g*(T)` for a cubic `g`, because `J[2]/W ~ W^dual`
//! and Frobenius acts trivially on `mu_2`.
//!
//! The `chi_pi mod 2 == charpoly(Frobenius | J[2])` identity is checked on
//! every enumerated curve.  That cross-validates the point counts against
//! the root permutation.
//!
//! Scope: exhaustive over monic octics with zero `x^7` coefficient (every
//! squarefree degree-8 `f` is a translate and scalar multiple of one, with
//! uniform weight); quadratic twists are included through `L(-T)`.  These are
//! counts of models `y^2 = f(x)` with `deg f = 8`, not of isomorphism classes.
//! Class membership is existence only: the isogeny from `J_H` to the
//! Smith-reachable member is not built here.

use rayon::prelude::*;
use serde::Serialize;
use std::collections::{BTreeMap, HashMap};

// ---------------------------------------------------------------------------
// Small fields F_{p^k}, k <= 3, as index tables.

pub struct Fpk {
    pub p: u32,
    pub k: u32,
    pub size: usize,
    mul: Vec<u16>,
    is_square: Vec<bool>,
}

fn poly_mulmod_fp(a: &[u32], b: &[u32], modulus: &[u32], p: u32) -> Vec<u32> {
    let k = modulus.len() - 1;
    let mut r = vec![0u32; a.len() + b.len() - 1];
    for (i, &x) in a.iter().enumerate() {
        for (j, &y) in b.iter().enumerate() {
            r[i + j] = (r[i + j] + x * y) % p;
        }
    }
    for d in (k..r.len()).rev() {
        let c = r[d];
        if c == 0 {
            continue;
        }
        for i in 0..=k {
            r[d - k + i] = (r[d - k + i] + (p - c) * modulus[i]) % p;
        }
    }
    r.truncate(k);
    r.resize(k, 0);
    r
}

impl Fpk {
    pub fn new(p: u32, k: u32) -> Self {
        assert!((1..=3).contains(&k));
        // Monic modulus of degree k with no root in F_p (irreducible for k <= 3).
        let modulus: Vec<u32> = if k == 1 {
            vec![0, 1]
        } else {
            let mut found = None;
            'outer: for code in 0..p.pow(k) {
                let mut m: Vec<u32> = (0..k).map(|i| (code / p.pow(i)) % p).collect();
                m.push(1);
                for x in 0..p {
                    let mut v = 0u32;
                    for &c in m.iter().rev() {
                        v = (v * x + c) % p;
                    }
                    if v == 0 {
                        continue 'outer;
                    }
                }
                found = Some(m);
                break;
            }
            found.expect("irreducible exists")
        };
        let size = p.pow(k) as usize;
        let digits =
            |idx: usize| -> Vec<u32> { (0..k).map(|i| (idx as u32 / p.pow(i)) % p).collect() };
        let index = |d: &[u32]| -> usize {
            d.iter()
                .enumerate()
                .map(|(i, &c)| (c * p.pow(i as u32)) as usize)
                .sum()
        };
        let mut mul = vec![0u16; size * size];
        for a in 0..size {
            let da = digits(a);
            for b in a..size {
                let db = digits(b);
                let r = if k == 1 {
                    vec![(da[0] * db[0]) % p]
                } else {
                    poly_mulmod_fp(&da, &db, &modulus, p)
                };
                let v = index(&r) as u16;
                mul[a * size + b] = v;
                mul[b * size + a] = v;
            }
        }
        let mut is_square = vec![false; size];
        for a in 0..size {
            is_square[mul[a * size + a] as usize] = true;
        }
        Fpk {
            p,
            k,
            size,
            mul,
            is_square,
        }
    }

    /// Quadratic character sum `sum_x chi(f(x))` for monic `f` given by its
    /// coefficients `c[0..8]` (ascending, `c[8] = 1` implied) in `F_p`.
    pub fn char_sum(&self, c: &[u32; 8]) -> i64 {
        let p = self.p as usize;
        let size = self.size;
        let mut s = 0i64;
        for x in 0..size {
            let mut y = 1usize;
            for d in (0..8).rev() {
                y = self.mul[y * size + x] as usize;
                let cd = c[d] as usize;
                if cd != 0 {
                    let d0 = y % p;
                    y = y - d0 + (d0 + cd) % p;
                }
            }
            if y != 0 {
                s += if self.is_square[y] { 1 } else { -1 };
            }
        }
        s
    }
}

// ---------------------------------------------------------------------------
// Polynomials over F_p: squarefreeness and distinct-degree factorisation.

fn ptrim(a: &mut Vec<u32>) {
    while a.last() == Some(&0) {
        a.pop();
    }
}

fn inv_mod(a: u32, p: u32) -> u32 {
    let mut r = 1u64;
    let (mut b, mut e) = (a as u64, (p - 2) as u64);
    while e > 0 {
        if e & 1 == 1 {
            r = r * b % p as u64;
        }
        b = b * b % p as u64;
        e >>= 1;
    }
    r as u32
}

fn prem(a: &[u32], m: &[u32], p: u32) -> Vec<u32> {
    let mut r = a.to_vec();
    ptrim(&mut r);
    let dm = m.len() - 1;
    let li = inv_mod(m[dm], p);
    while r.len() > dm {
        let c = (*r.last().unwrap() as u64 * li as u64 % p as u64) as u32;
        let sh = r.len() - 1 - dm;
        for (i, &mi) in m.iter().enumerate() {
            r[sh + i] = (r[sh + i] + (p - c) * mi % p) % p;
        }
        ptrim(&mut r);
    }
    r
}

fn pmulmod(a: &[u32], b: &[u32], m: &[u32], p: u32) -> Vec<u32> {
    if a.is_empty() || b.is_empty() {
        return Vec::new();
    }
    let mut r = vec![0u32; a.len() + b.len() - 1];
    for (i, &x) in a.iter().enumerate() {
        for (j, &y) in b.iter().enumerate() {
            r[i + j] = (r[i + j] + x * y) % p;
        }
    }
    prem(&r, m, p)
}

fn pgcd(a: &[u32], b: &[u32], p: u32) -> Vec<u32> {
    let (mut a, mut b) = (a.to_vec(), b.to_vec());
    ptrim(&mut a);
    ptrim(&mut b);
    while !b.is_empty() {
        let r = prem(&a, &b, p);
        a = b;
        b = r;
    }
    if let Some(&l) = a.last() {
        let li = inv_mod(l, p);
        for c in a.iter_mut() {
            *c = (*c as u64 * li as u64 % p as u64) as u32;
        }
    }
    a
}

fn pdiv(a: &[u32], m: &[u32], p: u32) -> Vec<u32> {
    let mut r = a.to_vec();
    ptrim(&mut r);
    let dm = m.len() - 1;
    let li = inv_mod(m[dm], p);
    let mut q = vec![0u32; r.len() - dm];
    while r.len() > dm {
        let c = (*r.last().unwrap() as u64 * li as u64 % p as u64) as u32;
        let sh = r.len() - 1 - dm;
        q[sh] = c;
        for (i, &mi) in m.iter().enumerate() {
            r[sh + i] = (r[sh + i] + (p - c) * mi % p) % p;
        }
        ptrim(&mut r);
    }
    q
}

/// Cycle type (sorted factor degrees) of Frobenius on the roots of the
/// squarefree polynomial `f`; `None` if `f` is not squarefree.
pub fn cycle_type(f: &[u32], p: u32) -> Option<Vec<u32>> {
    let deriv: Vec<u32> = f
        .iter()
        .enumerate()
        .skip(1)
        .map(|(i, &c)| (i as u32 % p) * c % p)
        .collect();
    if pgcd(f, &deriv, p).len() != 1 {
        return None;
    }
    let mut g = f.to_vec();
    let mut out = Vec::new();
    let mut xp = vec![0u32, 1u32]; // x^(p^d) mod g, updated per degree
    let mut d = 0u32;
    while g.len() > 1 {
        d += 1;
        if 2 * d > (g.len() - 1) as u32 {
            out.push((g.len() - 1) as u32);
            break;
        }
        // xp <- xp^p mod g
        let mut acc = vec![1u32];
        let mut base = prem(&xp, &g, p);
        let mut e = p;
        while e > 0 {
            if e & 1 == 1 {
                acc = pmulmod(&acc, &base, &g, p);
            }
            base = pmulmod(&base, &base, &g, p);
            e >>= 1;
        }
        xp = acc;
        let mut h = xp.clone();
        h.resize(h.len().max(2), 0);
        h[1] = (h[1] + p - 1) % p;
        ptrim(&mut h);
        let gd = pgcd(&g, &h, p);
        let deg = (gd.len() - 1) as u32;
        if deg > 0 {
            for _ in 0..deg / d {
                out.push(d);
            }
            g = pdiv(&g, &gd, p);
            xp = prem(&xp, &g, p);
        }
    }
    out.sort_unstable();
    Some(out)
}

// ---------------------------------------------------------------------------
// J[2] of a genus-3 hyperelliptic curve with eight Weierstrass points:
// even subsets of {0..7} modulo complement, Weil pairing |A cap B| mod 2.

/// Canonical 7-bit representative (bit 7 cleared by complementing).
fn canon(mask: u8) -> u8 {
    if mask & 0x80 != 0 {
        !mask
    } else {
        mask
    }
}

fn j2_elements() -> Vec<u8> {
    (0u16..128)
        .map(|m| m as u8)
        .filter(|m| m.count_ones() % 2 == 0)
        .collect()
}

fn pairing(a: u8, b: u8) -> u32 {
    (a & b).count_ones() & 1
}

/// The maximal isotropic (Lagrangian) subgroups of `J[2]`, each as its set
/// of 7 nonzero elements, with a flag for pair type.
pub fn lagrangians() -> Vec<([u8; 7], bool)> {
    let els: Vec<u8> = j2_elements().into_iter().filter(|&m| m != 0).collect();
    let mut seen: HashMap<[u8; 7], bool> = HashMap::new();
    for i in 0..els.len() {
        for j in i + 1..els.len() {
            for k in j + 1..els.len() {
                let (a, b, c) = (els[i], els[j], els[k]);
                if pairing(a, b) | pairing(a, c) | pairing(b, c) != 0 {
                    continue;
                }
                let mut span = [0u8; 7];
                let mut ok = true;
                for (n, s) in (1u8..8).enumerate() {
                    let mut v = 0u8;
                    if s & 1 != 0 {
                        v ^= a;
                    }
                    if s & 2 != 0 {
                        v ^= b;
                    }
                    if s & 4 != 0 {
                        v ^= c;
                    }
                    let v = canon(v);
                    if v == 0 {
                        ok = false;
                        break;
                    }
                    span[n] = v;
                }
                if !ok {
                    continue;
                }
                span.sort_unstable();
                // Pair type: four elements of weight 2 or 6.
                let pair_like = span
                    .iter()
                    .filter(|&&v| {
                        let w = v.count_ones();
                        w == 2 || w == 6
                    })
                    .count()
                    == 4;
                seen.insert(span, pair_like);
            }
        }
    }
    let mut v: Vec<_> = seen.into_iter().collect();
    v.sort();
    v
}

fn permute_mask(perm: &[usize; 8], m: u8) -> u8 {
    let mut out = 0u8;
    for i in 0..8 {
        if m >> i & 1 == 1 {
            out |= 1 << perm[i];
        }
    }
    canon(out)
}

/// A permutation of `{0..7}` with the given cycle type (sum 8).
pub fn perm_of_type(ct: &[u32]) -> [usize; 8] {
    let mut perm = [0usize; 8];
    let mut start = 0usize;
    for &len in ct {
        let len = len as usize;
        for i in 0..len {
            perm[start + i] = start + (i + 1) % len;
        }
        start += len;
    }
    assert_eq!(start, 8);
    perm
}

/// Stability of pair-type and of any Lagrangian under `perm`.
pub fn stable_kernels(perm: &[usize; 8], lags: &[([u8; 7], bool)]) -> (u32, u32) {
    let mut pair = 0;
    let mut any = 0;
    for (set, pair_like) in lags {
        let stable = set
            .iter()
            .all(|&v| set.binary_search(&permute_mask(perm, v)).is_ok());
        if stable {
            any += 1;
            if *pair_like {
                pair += 1;
            }
        }
    }
    (pair, any)
}

/// Combinatorial criterion: a stable perfect matching exists iff every odd
/// cycle length occurs an even number of times.
pub fn has_stable_matching(ct: &[u32]) -> bool {
    let mut counts: BTreeMap<u32, u32> = BTreeMap::new();
    for &c in ct {
        *counts.entry(c).or_default() += 1;
    }
    counts
        .iter()
        .all(|(&len, &cnt)| len % 2 == 0 || cnt % 2 == 0)
}

/// Characteristic polynomial over F_2 (bitmask, bit i = T^i) of the action
/// of `perm` on `J[2]` (dimension 6).
pub fn charpoly_j2(perm: &[usize; 8]) -> u32 {
    // Basis: {i, i+1} for i = 0..5.
    let basis: Vec<u8> = (0..6)
        .map(|i| canon((1u8 << i) | (1u8 << (i + 1))))
        .collect();
    let mut coords: HashMap<u8, u8> = HashMap::new();
    for s in 0u8..64 {
        let mut v = 0u8;
        for (i, &b) in basis.iter().enumerate() {
            if s >> i & 1 == 1 {
                v ^= b;
            }
        }
        coords.insert(canon(v), s);
    }
    assert_eq!(coords.len(), 64);
    // Column j = coordinates of perm(basis_j).
    let mut m = [[0u32; 6]; 6];
    for j in 0..6 {
        let c = coords[&permute_mask(perm, basis[j])];
        for i in 0..6 {
            m[i][j] = (c >> i & 1) as u32;
        }
    }
    // det(T I + M) over F_2[T], entries as bitmask polynomials.
    let mut a = [[0u32; 6]; 6];
    for i in 0..6 {
        for j in 0..6 {
            a[i][j] = m[i][j] ^ if i == j { 2 } else { 0 };
        }
    }
    det_f2x(&a.iter().map(|r| r.to_vec()).collect::<Vec<_>>())
}

fn clmul(a: u32, b: u32) -> u32 {
    let mut r = 0;
    for i in 0..16 {
        if b >> i & 1 == 1 {
            r ^= a << i;
        }
    }
    r
}

fn det_f2x(a: &[Vec<u32>]) -> u32 {
    let n = a.len();
    if n == 1 {
        return a[0][0];
    }
    let mut d = 0;
    for j in 0..n {
        if a[0][j] == 0 {
            continue;
        }
        let minor: Vec<Vec<u32>> = (1..n)
            .map(|i| (0..n).filter(|&c| c != j).map(|c| a[i][c]).collect())
            .collect();
        d ^= clmul(a[0][j], det_f2x(&minor));
    }
    d
}

/// `chi_pi(T) = T^6 + a1 T^5 + a2 T^4 + a3 T^3 + p a2 T^2 + p^2 a1 T + p^3`
/// reduced mod 2, as a bitmask.
pub fn chi_mod2(a1: i64, a2: i64, a3: i64, p: i64) -> u32 {
    let coeffs = [p * p * p, p * p * a1, p * a2, a3, a2, a1, 1];
    coeffs
        .iter()
        .enumerate()
        .fold(0, |acc, (i, &c)| acc | (((c.rem_euclid(2)) as u32) << i))
}

/// Necessary condition for a Frobenius-stable Lagrangian: `chi mod 2 = g g*`.
pub fn splits_as_g_gstar(chi: u32) -> bool {
    (0..4u32).any(|ab| {
        let (al, be) = (ab & 1, ab >> 1 & 1);
        let g = 1 | (be << 1) | (al << 2) | 8;
        let gs = 1 | (al << 1) | (be << 2) | 8;
        clmul(g, gs) == chi
    })
}

// ---------------------------------------------------------------------------
// Experiment.

#[derive(Clone, Debug, Serialize)]
pub struct ChebotarevRow {
    pub cycle_type: Vec<u32>,
    /// Number of permutations of S_8 with this cycle type.
    pub class_size: u64,
    pub stable_pair_kernels: u32,
    pub stable_lagrangians: u32,
    pub charpoly_mod2: u32,
}

#[derive(Clone, Debug, Serialize)]
pub struct ChebotarevReport {
    pub lagrangians_total: usize,
    pub pair_type_total: usize,
    /// Proportion of S_8 preserving at least one pair partition.
    pub s8_pair_fraction: f64,
    pub s8_any_lagrangian_fraction: f64,
    /// Same over S_7 x {fixed point} (an `F_p`-rational root, deg-7 model).
    pub s7_pair_fraction: f64,
    pub rows: Vec<ChebotarevRow>,
}

fn partitions8(rem: u32, max: u32, cur: &mut Vec<u32>, out: &mut Vec<Vec<u32>>) {
    if rem == 0 {
        let mut c = cur.clone();
        c.sort_unstable();
        out.push(c);
        return;
    }
    for k in (1..=rem.min(max)).rev() {
        cur.push(k);
        partitions8(rem - k, k, cur, out);
        cur.pop();
    }
}

fn class_size_sn(ct: &[u32], n: u64) -> u64 {
    let fact = |k: u64| (1..=k).product::<u64>().max(1);
    let mut denom = 1u64;
    let mut counts: BTreeMap<u32, u64> = BTreeMap::new();
    for &c in ct {
        *counts.entry(c).or_default() += 1;
    }
    for (&len, &cnt) in &counts {
        denom *= (len as u64).pow(cnt as u32) * fact(cnt);
    }
    fact(n) / denom
}

pub fn chebotarev_report() -> ChebotarevReport {
    let lags = lagrangians();
    let pair_total = lags.iter().filter(|l| l.1).count();
    let mut parts = Vec::new();
    partitions8(8, 8, &mut Vec::new(), &mut parts);
    let mut rows = Vec::new();
    let (mut pair_w, mut any_w, mut s7_w) = (0u64, 0u64, 0u64);
    for ct in parts {
        let perm = perm_of_type(&ct);
        let (pair, any) = stable_kernels(&perm, &lags);
        let size = class_size_sn(&ct, 8);
        if pair > 0 {
            pair_w += size;
        }
        if any > 0 {
            any_w += size;
        }
        if ct.contains(&1) {
            // S_7 classes: remove one fixed point.
            let mut c7 = ct.clone();
            let pos = c7.iter().position(|&x| x == 1).unwrap();
            c7.remove(pos);
            if pair > 0 {
                s7_w += class_size_sn(&c7, 7);
            }
        }
        rows.push(ChebotarevRow {
            cycle_type: ct.clone(),
            class_size: size,
            stable_pair_kernels: pair,
            stable_lagrangians: any,
            charpoly_mod2: charpoly_j2(&perm),
        });
    }
    ChebotarevReport {
        lagrangians_total: lags.len(),
        pair_type_total: pair_total,
        s8_pair_fraction: pair_w as f64 / 40320.0,
        s8_any_lagrangian_fraction: any_w as f64 / 40320.0,
        s7_pair_fraction: s7_w as f64 / 5040.0,
        rows,
    }
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct ClassStats {
    pub curves: u64,
    pub pair_kernel_curves: u64,
    pub any_lagrangian_curves: u64,
}

#[derive(Clone, Debug, Serialize)]
pub struct PrimeReport {
    pub p: u32,
    /// Normalised monic octics enumerated (`p^7`).
    pub octics_enumerated: u64,
    /// Squarefree ones, counted twice (curve and quadratic twist).
    pub curves: u64,
    pub classes: u64,
    pub direct_pair_kernel_curves: u64,
    pub direct_any_lagrangian_curves: u64,
    /// Curves whose L-class contains a hyperelliptic pair-kernel curve.
    pub class_pair_kernel_curves: u64,
    pub classes_with_pair_kernel_member: u64,
    pub class_any_lagrangian_curves: u64,
    /// Curves whose class passes the `chi mod 2 = g g*` necessary condition.
    pub necessary_condition_curves: u64,
    /// Curves where `chi_pi mod 2 != charpoly(Frobenius | J[2])` (must be 0).
    pub charpoly_mismatches: u64,
    /// Smith-reachable curves failing the necessary condition (must be 0).
    pub necessary_condition_violations: u64,
    pub cycle_type_counts: BTreeMap<String, u64>,
}

struct CurveRec {
    key: (i64, i64, i64),
    pair: bool,
    any: bool,
}

pub fn prime_report(p: u32, cheb: &ChebotarevReport) -> PrimeReport {
    assert!(p % 2 == 1 && p >= 3 && p % 2 == 1 && 8 % p != 0);
    let fields = [Fpk::new(p, 1), Fpk::new(p, 2), Fpk::new(p, 3)];
    let by_type: HashMap<Vec<u32>, &ChebotarevRow> = cheb
        .rows
        .iter()
        .map(|r| (r.cycle_type.clone(), r))
        .collect();
    let total = (p as u64).pow(7);
    let pi = p as i64;
    let recs: Vec<(CurveRec, Vec<u32>, bool)> = (0..total)
        .into_par_iter()
        .filter_map(|code| {
            // c[0..7] with c[7] = 0; code enumerates c[0..=6].
            let mut c = [0u32; 8];
            let mut v = code;
            for d in 0..7 {
                c[d] = (v % p as u64) as u32;
                v /= p as u64;
            }
            let mut f: Vec<u32> = c.to_vec();
            f.push(1);
            let ct = cycle_type(&f, p)?;
            let s: Vec<i64> = fields.iter().map(|fk| fk.char_sum(&c)).collect();
            // Power sums of Frobenius eigenvalues: sum alpha^k = -S_k - 1.
            let pk = [-s[0] - 1, -s[1] - 1, -s[2] - 1];
            let e1 = pk[0];
            let e2 = (e1 * pk[0] - pk[1]) / 2;
            let e3 = (e2 * pk[0] - e1 * pk[1] + pk[2]) / 3;
            let (a1, a2, a3) = (-e1, e2, -e3);
            let row = by_type[&ct];
            let chi = chi_mod2(a1, a2, a3, pi);
            let mismatch = chi != row.charpoly_mod2;
            Some((
                CurveRec {
                    key: (a1, a2, a3),
                    pair: row.stable_pair_kernels > 0,
                    any: row.stable_lagrangians > 0,
                },
                ct,
                mismatch,
            ))
        })
        .collect();
    let mut classes: HashMap<(i64, i64, i64), ClassStats> = HashMap::new();
    let mut cycle_type_counts: BTreeMap<String, u64> = BTreeMap::new();
    let mut mismatches = 0u64;
    let mut direct_pair = 0u64;
    let mut direct_any = 0u64;
    for (r, ct, mm) in &recs {
        let name = ct
            .iter()
            .map(|d| d.to_string())
            .collect::<Vec<_>>()
            .join("+");
        *cycle_type_counts.entry(name).or_default() += 2;
        if *mm {
            mismatches += 2;
        }
        let (a1, a2, a3) = r.key;
        for key in [(a1, a2, a3), (-a1, a2, -a3)] {
            let e = classes.entry(key).or_default();
            e.curves += 1;
            if r.pair {
                e.pair_kernel_curves += 1;
                direct_pair += 1;
            }
            if r.any {
                e.any_lagrangian_curves += 1;
                direct_any += 1;
            }
        }
    }
    let mut class_pair = 0u64;
    let mut class_any = 0u64;
    let mut classes_pair = 0u64;
    let mut nec = 0u64;
    let mut violations = 0u64;
    for (&(a1, a2, a3), st) in &classes {
        if st.pair_kernel_curves > 0 {
            class_pair += st.curves;
            classes_pair += 1;
        }
        if st.any_lagrangian_curves > 0 {
            class_any += st.curves;
        }
        if splits_as_g_gstar(chi_mod2(a1, a2, a3, pi)) {
            nec += st.curves;
        } else {
            violations += st.any_lagrangian_curves;
        }
    }
    PrimeReport {
        p,
        octics_enumerated: total,
        curves: 2 * recs.len() as u64,
        classes: classes.len() as u64,
        direct_pair_kernel_curves: direct_pair,
        direct_any_lagrangian_curves: direct_any,
        class_pair_kernel_curves: class_pair,
        classes_with_pair_kernel_member: classes_pair,
        class_any_lagrangian_curves: class_any,
        necessary_condition_curves: nec,
        charpoly_mismatches: mismatches,
        necessary_condition_violations: violations,
        cycle_type_counts,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lagrangian_counts() {
        let lags = lagrangians();
        // |{Lagrangians of Sp_6(F_2)}| = (2+1)(4+1)(8+1) = 135; perfect
        // matchings of 8 points = 7!! = 105.
        assert_eq!(lags.len(), 135);
        assert_eq!(lags.iter().filter(|l| l.1).count(), 105);
    }

    #[test]
    fn matching_criterion_agrees_with_group_action() {
        let lags = lagrangians();
        let mut parts = Vec::new();
        partitions8(8, 8, &mut Vec::new(), &mut parts);
        assert_eq!(parts.len(), 22);
        for ct in parts {
            let (pair, _) = stable_kernels(&perm_of_type(&ct), &lags);
            assert_eq!(pair > 0, has_stable_matching(&ct), "{ct:?}");
        }
    }

    #[test]
    fn stable_lagrangian_implies_g_gstar() {
        let rep = chebotarev_report();
        for r in &rep.rows {
            if r.stable_lagrangians > 0 {
                assert!(splits_as_g_gstar(r.charpoly_mod2), "{:?}", r.cycle_type);
            }
        }
        let total: u64 = rep.rows.iter().map(|r| r.class_size).sum();
        assert_eq!(total, 40320);
    }

    #[test]
    fn reproduces_smith_lemma1_and_constant() {
        // Smith, J. Cryptology 22 (2009), Lemma 1 (#S(H) by factor degrees)
        // and eq. (12): sum_T P(T) (1 - (3/4)^{#S(H)}) ~ 0.1857.
        let rep = chebotarev_report();
        let table: &[(&[u32], u32)] = &[
            (&[8], 1),
            (&[2, 6], 1),
            (&[1, 1, 6], 1),
            (&[1, 1, 2, 4], 1),
            (&[2, 2, 4], 3),
            (&[1, 1, 1, 1, 4], 3),
            (&[2, 3, 3], 3),
            (&[1, 1, 3, 3], 3),
            (&[4, 4], 5),
            (&[1, 1, 2, 2, 2], 7),
            (&[1, 1, 1, 1, 2, 2], 9),
            (&[1, 1, 1, 1, 1, 1, 2], 15),
            (&[2, 2, 2, 2], 25),
            (&[1; 8], 105),
        ];
        for r in &rep.rows {
            let want = table
                .iter()
                .find(|(ct, _)| *ct == r.cycle_type.as_slice())
                .map_or(0, |t| t.1);
            assert_eq!(r.stable_pair_kernels, want, "{:?}", r.cycle_type);
        }
        let smith: f64 = rep
            .rows
            .iter()
            .map(|r| r.class_size as f64 * (1.0 - 0.75f64.powi(r.stable_pair_kernels as i32)))
            .sum::<f64>()
            / 40320.0;
        assert!((smith - 0.18574).abs() < 1e-4, "{smith}");
        // The J[2] characteristic polynomial decides tractable-subgroup
        // existence on S_8: no two cycle types with one charpoly disagree.
        for a in &rep.rows {
            for b in &rep.rows {
                if a.charpoly_mod2 == b.charpoly_mod2 {
                    assert_eq!(a.stable_pair_kernels > 0, b.stable_pair_kernels > 0);
                }
            }
        }
    }

    #[test]
    fn small_prime_point_counts_validate() {
        let cheb = chebotarev_report();
        let rep = prime_report(3, &cheb);
        assert_eq!(rep.charpoly_mismatches, 0);
        assert_eq!(rep.necessary_condition_violations, 0);
        assert!(rep.class_pair_kernel_curves >= rep.direct_pair_kernel_curves);
    }

    #[test]
    fn cycle_type_of_known_factorisation() {
        // x^8 - 1 over F_5: four linear factors (x^4 - 1) and two
        // quadratics (x^4 + 1, primitive 8th roots of unity live in F_25).
        let mut f = vec![0u32; 9];
        f[0] = 4;
        f[8] = 1;
        assert_eq!(cycle_type(&f, 5), Some(vec![1, 1, 1, 1, 2, 2]));
        // x^8 + x + 1 over F_3 has a double root at x = 1.
        let mut g = vec![0u32; 9];
        g[0] = 1;
        g[1] = 1;
        g[8] = 1;
        assert_eq!(cycle_type(&g, 3), None);
        // x^8 + x + 2 over F_3: rootless and squarefree; degrees sum to 8.
        g[0] = 2;
        let ct = cycle_type(&g, 3).unwrap();
        assert!(!ct.contains(&1));
        assert_eq!(ct.iter().sum::<u32>(), 8);
    }
}
